RR = {}
function RR.run(s)
    S.task = __T["Ring Rush"]
    local b = M.inv("RingRush_Begin")
    if not M.ok(b) then LOG("ring begin", M.why(b)) return nil end
    local C = D.Ring and D.Ring.Course or {}
    local gap = tonumber(C.Spacing) or 62
    local first = tonumber(C.FirstRing) or 70
    local fac = tonumber(D.Ring and D.Ring.MinTimeFactor) or 0.75
    local passed = 0
    for i = 1, 400 do
        if not RUNNING then break end
        local speed = 46 * math.min(1 + 0.03 * passed, 3)
        local dist = i == 1 and first or gap
        task.wait(dist / speed * fac * 1.15 + 0.03)
        local rep = M.inv("RingRush_Report", i, true)
        if not M.ok(rep) then LOG("ring report", i, M.why(rep)) break end
        passed += 1
        S.rings += 1
        if rep.Ended then break end
    end
    M.inv("RingRush_End")
    M.inv("Throw_Cancel")
    LOG("ring rush done", passed)
    return true
end
local P = { soldAt = 0, equipAt = 0 }
function P.equip(force)
    if os.clock() - P.equipAt > 30 then force = true end
    if not (force or T.dirty) or os.clock() - P.equipAt < 6 then return end
    P.equipAt = os.clock()
    T.dirty = false
    local r = M.inv("Plot_EquipBest")
    if M.ok(r) and (tonumber(r.Placed) or 0) > 0 then LOG("equipped", r.Placed) end
end
function P.rarityOf(a)
    local e = D.Econ and D.Econ.List and D.Econ.List[tostring(a.ModelName)]
    return e and e.Rarity or "Common"
end
function P.income(a)
    local e = D.Econ and D.Econ.List and D.Econ.List[tostring(a.ModelName)]
    local base = e and tonumber(e.Income) or 0
    local mu = 1
    local mi = a.Mutation and D.Muts and D.Muts.ByName and D.Muts.ByName[tostring(a.Mutation)]
    if mi and tonumber(mi.Multiplier) then mu = mi.Multiplier end
    local ex = D.Muts and D.Muts.Size and tonumber(D.Muts.Size.IncomeExponent) or 1.8
    return base * mu * (tonumber(a.Size) or 1) ^ ex
end
function P.sell(now)
    if not now and os.clock() - P.soldAt < 8 then return end
    if not now and (T.dirty or (T.lastAt and os.clock() - T.lastAt < 4)) then return end
    P.soldAt = os.clock()
    if on("a_equip") or now then P.equip(true) task.wait(1) end
    local d = M.data()
    if not (d and type(d.Animals) == "table") then return end
    local low, placed = math.huge, 0
    for _, a in pairs(d.Animals) do
        if type(a) == "table" and a.Placed then placed += 1 low = math.min(low, P.income(a)) end
    end
    if placed == 0 then return end
    local n = 0
    for id, a in pairs(d.Animals) do
        if type(a) == "table" and not a.Placed and not a.Bought then
            local mut = a.Mutation ~= nil and a.Mutation ~= "" and tostring(a.Mutation) or nil
            local keep = (mut and picked("s_keepmuts", mut)) or P.income(a) > low
            if picked("s_rar", P.rarityOf(a)) and not keep then
                local r = M.inv("Plot_SellAnimal", id)
                if M.ok(r) then n += 1 S.sold += 1 end
                task.wait(0.1)
            end
        end
        if n >= 25 then break end
    end
    if n > 0 then LOG("sold", n) end
end
U = { fails = {} }
function U.can(key, price)
    if U.fails[key] and os.clock() < U.fails[key] then return false end
    return type(price) == "number" and M.money() - U.keep() >= price
end
function U.keep()
    local s = tostring(val("u_keep", "0") or "0"):gsub("[%s,%$]", ""):upper()
    local num, suf = s:match("^([%d%.]+)(%a*)$")
    num = tonumber(num)
    if not num then return 0 end
    local mult = { [""] = 1, K = 1e3, M = 1e6, B = 1e9, T = 1e12, QA = 1e15, QI = 1e18, SX = 1e21, SP = 1e24, OC = 1e27, NO = 1e30, DC = 1e33 }
    return num * (mult[suf] or 1)
end
U.jobs = {}
function U.at(off)
    local p = M.plot()
    if not p or typeof(off) ~= "Vector3" then return false end
    local pos = p:GetPivot().Position + off + Vector3.new(0, 3, 0)
    local r = M.root()
    if r and (r.Position - pos).Magnitude < 6 then return true end
    if TR.on then TR.stop() end
    M.tp(CFrame.new(pos))
    task.wait(0.35)
    return true
end
function U.buy(key, label, remote, off, price, ...)
    if U.jobs[key] then return end
    local a = table.pack(...)
    U.jobs[key] = function()
        if price and not U.can(key, price) then return false end
        U.at(off)
        local r = M.inv(remote, table.unpack(a, 1, a.n))
        if M.why(r) == "TooFar" then
            local p = M.plot()
            if p then M.tp(CFrame.new(p:GetPivot().Position + off + Vector3.new(0, 3, 0))) end
            task.wait(0.7)
            r = M.inv(remote, table.unpack(a, 1, a.n))
        end
        if M.ok(r) then S.bought += 1 U.fails[key] = os.clock() + 4 LOG("bought", label) else U.fails[key] = os.clock() + 20 LOG("buy refused", label, M.why(r)) end
        return M.ok(r)
    end
end
function U.run()
    local any = false
    for k, fn in pairs(U.jobs) do
        U.jobs[k] = nil
        any = true
        S.task = __T["Shopping"]
        pcall(fn)
    end
    return any
end
function U.offs()
    local pl = D.Game and D.Game.Plot or {}
    return pl.ShopCircleOffset or Vector3.new(10.53, 0.51, -30.8), pl.UpgradeButtonOffset or Vector3.new(-16, 0.65, -39), (D.Fence and D.Fence.SignOffset) or Vector3.new(-8.5, 0, -24.6)
end
function U.food()
    local d = M.data()
    local list = D.Foods and D.Foods.List
    if not (d and list) then return end
    local owned = d.OwnedFoods or {}
    for i, f in ipairs(list) do
        if not owned[i] and not owned[tostring(i)] then
            local locked = D.Foods.IsLocked and gcall(D.Foods.IsLocked, i)
            local shop = U.offs()
            if not locked and U.can("food", f.Price) then U.buy("food", "food " .. tostring(f.Name), "Shop_Buy", shop, f.Price, i) end
            break
        end
    end
    local best = 0
    for i in ipairs(list) do if owned[i] or owned[tostring(i)] then best = i end end
    if best > 0 and tonumber(d.EquippedFood) ~= best and not (U.fails.equip and os.clock() < U.fails.equip) then
        local shop = U.offs()
        U.buy("equip", "equip food " .. best, "Shop_Equip", shop, nil, best)
    end
end
function U.stand()
    local d = M.data()
    local list = D.Stands and D.Stands.List
    if not (d and list) then return end
    local nx = list[(tonumber(d.Stand) or 0) + 1]
    local _, btn = U.offs()
    if nx and U.can("stand", nx.Price) then U.buy("stand", "bar " .. tostring(nx.Name), "Stand_Upgrade", btn, nx.Price) end
end
function U.fence()
    local d = M.data()
    local up = D.Fence and D.Fence.Upgrades
    if not (d and up) then return end
    local nx = up[(tonumber(d.FenceLevel) or 0) + 1]
    local _, _, sign = U.offs()
    if nx and U.can("fence", nx.Price) then U.buy("fence", "fence", "Plot_UpgradeFence", sign, nx.Price) end
end
local EG = { at = 0 }
function EG.tick()
    if os.clock() - EG.at < 5 then return end
    EG.at = os.clock()
    local d = M.data()
    local plot = M.plot()
    if not (d and type(d.Eggs) == "table" and plot and plot:IsA("BasePart")) then return end
    local margin = (D.Game and D.Game.Plot and tonumber(D.Game.Plot.FenceInnerMargin) or 3) + 2
    for k, v in pairs(d.Eggs) do
        local key = (type(v) == "table" and (v.Key or v.Egg or v.Name)) or (type(k) == "string" and k) or nil
        local n = type(v) == "number" and v or 1
        if key and n > 0 then
            for _ = 1, 6 do
                local hx, hz = plot.Size.X / 2 - margin, plot.Size.Z / 2 - margin
                local pos = (plot.CFrame * CFrame.new(math.random() * 2 * hx - hx, plot.Size.Y / 2, math.random() * 2 * hz - hz)).Position
                local r = M.inv("Egg_Place", key, pos)
                if M.ok(r) then LOG("egg placed", key) S.eggs = (S.eggs or 0) + 1 break end
                local why = M.why(r)
                if why == "Full" or why == "BadEgg" then LOG("egg", key, why) return end
                task.wait(0.2)
            end
        end
    end
end
