task.spawn(function()
    while RUNNING do
        pcall(function()
            local mins = math.max((os.clock() - S.t0) / 60, 0.25)
            setText(UI.s1, string.format(__T["Money $%s · +$%s/s"], M.short(M.money()), M.short(lp:GetAttribute("IncomeRate") or 0)))
            setText(UI.s2, string.format(__T["Throw Power %s"], tostring(M.stat("Throw Power") or "-")))
            setText(UI.s3, __T["Doing: "] .. S.task .. ((S.gtext and os.clock() - S.gmsgAt < 6) and (" · " .. S.gtext) or ""))
            setText(UI.s4, string.format(__T["Throws %d · Perfect %d · %.1f/min"], S.throws, S.perfect, S.throws / mins))
            setText(UI.s5, __T["Last: "] .. tostring(S.last or "-"))
            setText(UI.s6, __T["Best: "] .. tostring(S.best))
            setText(UI.s7, string.format(__T["Sold %d · Bought %d · 2x %d%s%s"], S.sold, S.bought, S.bonus, S.luckyUsed > 0 and (__T[" · Lucky "] .. S.luckyUsed) or "", S.rings > 0 and (__T[" · Rings "] .. S.rings) or ""))
            local d = M.data()
            if d and UI.next then
                local f = D.Foods and D.Foods.List
                local nf
                for i, x in ipairs(f or {}) do if not (d.OwnedFoods or {})[i] then nf = x break end end
                local ns = D.Stands and D.Stands.List and D.Stands.List[(tonumber(d.Stand) or 0) + 1]
                local nfe = D.Fence and D.Fence.Upgrades and D.Fence.Upgrades[(tonumber(d.FenceLevel) or 0) + 1]
                setText(UI.next, string.format(__T["Next food: %s\nNext bar: %s\nNext fence: %s"],
                    nf and (nf.Name .. " $" .. M.short(nf.Price)) or "all owned",
                    ns and (ns.Name .. " $" .. M.short(ns.Price)) or "max",
                    nfe and ("$" .. M.short(nfe.Price)) or "max"))
            end
        end)
        task.wait(0.5)
    end
end)
onClean(function() pcall(function() Library:Unload() end) end)
pcall(function()
    local name, ok, err = SaveManager:GetAutoloadConfig()
    local loaded = false
    if ok and not err then
        loaded = SaveManager:Load(name) == true
        if not loaded then SaveManager.Library:Notify("Autoload config not found, using last settings") end
    end
    if not loaded and isfile and isfile("COMBO_WICK_TFFA/settings/auto.json") then SaveManager:Load("auto") end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() if not SaveManager.Library.Unloaded then SaveManager:Save("auto") end end) end end)
    end
    local function skip(k) k = tostring(k); return k == "f_pause" or k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
function UI.center()
    pcall(function()
        local sg = Library.ScreenGui
        local m = sg and sg:FindFirstChild("Main")
        if not m then return end
        m.AnchorPoint = Vector2.zero
        for _ = 1, 3 do
            local vs, sz, cur = sg.AbsoluteSize, m.AbsoluteSize, m.AbsolutePosition
            local tx, ty = math.max(0, math.floor((vs.X - sz.X) / 2)), math.max(0, math.floor((vs.Y - sz.Y) / 2))
            local k = (m.Size.X.Offset > 0 and sz.X / m.Size.X.Offset) or 1
            if math.abs(cur.X - tx) < 2 and math.abs(cur.Y - ty) < 2 then break end
            m.Position = UDim2.new(m.Position.X.Scale, m.Position.X.Offset + (tx - cur.X) / k, m.Position.Y.Scale, m.Position.Y.Offset + (ty - cur.Y) / k)
            RunService.Heartbeat:Wait()
        end
    end)
end
for _, d in ipairs({ 1, 3, 6 }) do task.delay(d, UI.center) end
task.defer(function() if on("pl_pause") then M.antiPause(true) end end)
task.spawn(function()
    local miss = {}
    for _, n in ipairs(getgenv().CW_NEEDS or {}) do if not CAP.cap(n) then miss[#miss + 1] = n end end
    if #miss > 0 then
        setText(UI.exec, '<font color="#ff6b6b">' .. __T["Missing on your executor: "] .. table.concat(miss, ", ") .. __T[". Auto Sell, Auto Buy and the stats won't work."] .. '</font>')
    else
        setText(UI.exec, '<font color="#7ED957">' .. __T["Executor check: all features supported"] .. '</font>')
    end
    LOG("exec check", "missing=" .. table.concat(miss, ","))
end)
notify(__T["Loaded"])

